[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CreativeHub — Online courses for creative professionals</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
/* ── Hero Carousel ── */
.hero-carousel {
  position: relative;
  background: #171717;
  overflow: hidden;
  min-height: 480px;
}
.hero-slide {
  display: none;
  padding: 60px 40px;
  max-width: 1280px;
  margin: 0 auto;
  gap: 48px;
  align-items: center;
}
.hero-slide.active { display: flex; }
.hero-slide-content { flex: 1; color: #fff; }
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(0,230,180,0.15);
  border: 1px solid #00E6B4;
  color: #00E6B4;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.hero-title {
  font-family: 'Inter', sans-serif;
  font-size: clamp(26px, 4vw, 42px);
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: 16px;
  color: #fff;
}
.hero-desc {
  font-size: 15px;
  line-height: 1.65;
  color: #ccc;
  margin-bottom: 24px;
  max-width: 500px;
}
.hero-meta {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.hero-meta-item { display: flex; align-items: center; gap: 6px; font-size: 13px; color: #aaa; }
.hero-meta-item svg { width: 15px; height: 15px; }
.hero-rating { color: #F02D00; font-weight: 700; }
.hero-pricing {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.hero-price-new { font-size: 32px; font-weight: 800; color: #fff; }
.hero-price-old { font-size: 18px; color: #888; text-decoration: line-through; }
.hero-price-badge {
  background: #F02D00;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
}
.hero-cta-row { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.hero-cta-free {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #00E6B4;
  color: #111;
  font-weight: 700;
  font-size: 13px;
  padding: 4px 14px 4px 6px;
  border-radius: 20px;
}
.hero-cta-free span.tag { background: #171717; color: #00E6B4; border-radius: 14px; padding: 2px 8px; font-size: 10px; font-weight: 800; text-transform: uppercase; }
.hero-slide-visual { flex: 0 0 400px; }
.hero-card-preview {
  background: linear-gradient(135deg, #222 0%, #1a1a1a 100%);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid #333;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5);
}
.hero-card-img {
  width: 100%;
  height: 230px;
  object-fit: cover;
  display: block;
  background: linear-gradient(135deg, #2a2a2a 0%, #3a3a3a 100%);
}
.hero-card-body { padding: 20px; }
.hero-card-tag { font-size: 11px; font-weight: 600; color: #00E6B4; text-transform: uppercase; letter-spacing: 0.07em; margin-bottom: 8px; }
.hero-card-title { font-size: 16px; font-weight: 700; color: #fff; margin-bottom: 6px; line-height: 1.4; }
.hero-card-instructor { font-size: 13px; color: #888; }
/* Carousel Controls */
.carousel-controls {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
}
.carousel-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: #555;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  padding: 0;
}
.carousel-dot.active { background: #F02D00; width: 24px; border-radius: 4px; }
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.15);
  color: #fff;
  width: 44px; height: 44px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background 0.2s;
  backdrop-filter: blur(4px);
}
.carousel-arrow:hover { background: rgba(255,255,255,0.2); }
.carousel-prev { left: 16px; }
.carousel-next { right: 16px; }

/* ── Course Grid ── */
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 28px;
  flex-wrap: wrap;
  gap: 12px;
}
.section-title { font-size: clamp(22px, 3vw, 30px); font-weight: 800; color: #171717; }
.section-link { font-size: 14px; font-weight: 600; color: #F02D00; text-decoration: none; }
.section-link:hover { text-decoration: underline; }

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.course-card {
  background: #fff;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid #eee;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
}
.course-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.12); }
.course-card-img {
  width: 100%;
  height: 160px;
  object-fit: cover;
  display: block;
}
.course-card-img-placeholder {
  width: 100%;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.course-card-body { padding: 16px; }
.course-card-title { font-size: 15px; font-weight: 700; color: #171717; margin-bottom: 6px; line-height: 1.4; }
.course-card-instructor { font-size: 12px; color: #888; margin-bottom: 8px; }
.course-card-meta { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; flex-wrap: wrap; }
.course-card-rating { font-size: 12px; font-weight: 700; color: #171717; }
.course-card-students { font-size: 12px; color: #888; }
.course-card-footer { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; }
.course-card-price { font-size: 18px; font-weight: 800; color: #171717; }
.course-card-price-old { font-size: 13px; color: #aaa; text-decoration: line-through; }
.badge-bestseller {
  background: #171717;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.badge-discount {
  background: #F02D00;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
}

/* ── Course Carousel (horizontal scroll) ── */
.course-carousel-wrapper { position: relative; }
.course-carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  -ms-overflow-style: none;
  scrollbar-width: none;
  padding-bottom: 4px;
}
.course-carousel::-webkit-scrollbar { display: none; }
.course-carousel .course-card { flex: 0 0 260px; }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: #fff;
  border: 1px solid #e0e0e0;
  color: #171717;
  width: 44px; height: 44px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  box-shadow: 0 4px 16px rgba(0,0,0,0.12);
  z-index: 2;
  transition: box-shadow 0.2s;
}
.carousel-btn:hover { box-shadow: 0 6px 24px rgba(0,0,0,0.18); }
.carousel-btn-prev { left: -20px; }
.carousel-btn-next { right: -20px; }

/* ── Value Propositions ── */
.value-props-section { background: #171717; padding: 80px 0; }
.value-props-section .section-title { color: #fff; text-align: center; margin-bottom: 48px; }
