.value-prop-item { display: flex; gap: 16px; }
.value-prop-icon {
  flex: 0 0 44px;
  width: 44px; height: 44px;
  background: rgba(240,45,0,0.15);
  border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
