.thumb-h1 { background: linear-gradient(135deg, #0f3460 0%, #533483 100%); }
.thumb-h2 { background: linear-gradient(135deg, #e94560 0%, #f5a623 100%); }
.thumb-h3 { background: linear-gradient(135deg, #16213e 0%, #0f3460 100%); }

@media (max-width: 768px) {
  .hero-slide { flex-direction: column; padding: 40px 20px; min-height: auto; }
  .hero-slide-visual { display: none; }
  .carousel-btn-prev { left: -12px; }
  .carousel-btn-next { right: -12px; }
}
</style>
