// Hero Carousel
let heroIdx = 0;
const heroSlides = document.querySelectorAll('.hero-slide');
const heroDots = document.querySelectorAll('.carousel-dot');

function heroGoTo(idx) {
  heroSlides[heroIdx].classList.remove('active');
  heroDots[heroIdx].classList.remove('active');
  heroDots[heroIdx].setAttribute('aria-selected', 'false');
  heroIdx = (idx + heroSlides.length) % heroSlides.length;
  heroSlides[heroIdx].classList.add('active');
  heroDots[heroIdx].classList.add('active');
  heroDots[heroIdx].setAttribute('aria-selected', 'true');
}

function heroSlide(dir) { heroGoTo(heroIdx + dir); }

// Auto-advance hero carousel
setInterval(() => heroSlide(1), 5000);

// Horizontal carousel scroll
function scrollCarousel(id, dir) {
  const el = document.getElementById(id);
  el.scrollBy({ left: dir * 560, behavior: 'smooth' });
}

// Countdown timer
function updateCountdown() {
  const el = document.getElementById('countdown');
  if (!el) return;
  const parts = el.textContent.split(':').map(Number);
  let [h, m, s] = parts;
  s--;
  if (s < 0) { s = 59; m--; }
  if (m < 0) { m = 59; h--; }
  if (h < 0) { h = 23; m = 59; s = 59; }
  el.textContent = [h, m, s].map(n => String(n).padStart(2, '0')).join(':');
}
setInterval(updateCountdown, 1000);
</script>
