/* ── CreativeHub Shared Styles ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #F02D00;
  --dark: #171717;
  --teal: #00E6B4;
  --white: #FFFFFF;
  --gray-50: #f9f9f9;
  --gray-100: #f3f3f3;
  --gray-200: #e8e8e8;
  --gray-400: #aaa;
  --gray-600: #666;
  --gray-800: #333;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 4px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.1);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.14);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'DM Sans', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: #fff;
  -webkit-font-smoothing: antialiased;
}

/* ── Typography ── */
h1, h2, h3, h4, h5, h6 {
  font-family: 'Inter', sans-serif;
  font-weight: 700;
  line-height: 1.2;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; height: auto; display: block; }

/* ── Layout ── */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 40px;
}

.page-section { padding: 72px 0; }

@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .page-section { padding: 48px 0; }
}

/* ── Promo Banner ── */
.promo-banner {
  background: var(--dark);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px;
  font-size: 13px;
  font-weight: 500;
  position: sticky;
  top: 0;
  z-index: 1000;
}
.promo-banner-inner {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  justify-content: center;
  flex-wrap: wrap;
}
.countdown {
  font-weight: 800;
  color: var(--teal);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}
.promo-cta {
  background: var(--red);
  color: #fff;
  font-weight: 700;
  font-size: 12px;
  padding: 4px 12px;
  border-radius: 20px;
  text-decoration: none;
  transition: opacity var(--transition);
}
.promo-cta:hover { opacity: 0.85; }
.promo-close {
  background: none;
  border: none;
  color: rgba(255,255,255,0.6);
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  transition: color var(--transition);
  flex-shrink: 0;
}
.promo-close:hover { color: #fff; }

/* ── Header ── */
.site-header {
  background: #fff;
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 37px;
  z-index: 900;
}
.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 40px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  font-weight: 800;
  color: var(--dark);
  text-decoration: none;
  flex-shrink: 0;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link {
  font-size: 14px;
  font-weight: 500;
  color: var(--dark);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  transition: background var(--transition), color var(--transition);
  text-decoration: none;
}
.nav-link:hover { background: var(--gray-100); }
.nav-link-plus {
  color: var(--red);
  font-weight: 700;
}
.nav-link-plus:hover { background: rgba(240,45,0,0.08); }

.header-search {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--gray-100);
  border: 1px solid var(--gray-200);
  border-radius: 24px;
  padding: 9px 16px;
  max-width: 400px;
  color: var(--gray-600);
}
.header-search input {
  border: none;
  background: none;
  outline: none;
  font-size: 14px;
  color: var(--dark);
  width: 100%;
  font-family: inherit;
}
.header-search input::placeholder { color: var(--gray-400); }

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.btn-ghost {
  font-size: 14px;
  font-weight: 600;
  color: var(--dark);
  padding: 8px 16px;
  border-radius: 8px;
  border: 1px solid var(--gray-200);
  background: transparent;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-ghost:hover { background: var(--gray-100); border-color: #ccc; }

.btn-primary {
  font-size: 14px;
  font-weight: 700;
  color: #fff;
  background: var(--red);
  padding: 9px 20px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: opacity var(--transition), transform var(--transition);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-primary:hover { opacity: 0.88; transform: translateY(-1px); }
.btn-primary:active { transform: translateY(0); }

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--dark);
  padding: 4px;
  margin-left: auto;
}

@media (max-width: 900px) {
  .header-inner { padding: 0 20px; gap: 16px; }
  .header-search { max-width: 200px; }
}
@media (max-width: 768px) {
  .mobile-menu-btn { display: flex; }
  .site-nav {
    display: none;
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background: #fff;
    flex-direction: column;
    align-items: stretch;
    padding: 12px;
    border-bottom: 1px solid var(--gray-200);
    box-shadow: var(--shadow-md);
    gap: 0;
  }
  .site-nav.open { display: flex; }
  .nav-link { padding: 12px; border-radius: 0; }
  .header-search { display: none; }
  .header-actions { gap: 6px; }
  .btn-ghost { display: none; }
  .site-header { top: 37px; }
}

/* ── Footer ── */
.site-footer {
  background: var(--dark);
  color: #fff;
  padding: 60px 0 0;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.footer-heading {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.5);
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
}
.footer-chevron { transition: transform 0.2s; }
.footer-heading.open .footer-chevron { transform: rotate(180deg); }
.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.65);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  padding: 28px 0 32px;
}
.footer-logo-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 20px;
}
.footer-legal-links {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-legal-links a {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-legal-links a:hover { color: rgba(255,255,255,0.8); }
.footer-languages {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.footer-languages span {
  font-size: 12px;
  color: rgba(255,255,255,0.45);
  cursor: pointer;
  transition: color var(--transition);
}
.footer-languages span:hover { color: rgba(255,255,255,0.8); }

@media (max-width: 900px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid rgba(255,255,255,0.08); }
  .footer-heading { padding: 16px 0; margin-bottom: 0; }
  .footer-links { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
  .footer-links.open { max-height: 500px; padding-bottom: 16px; }
  .footer-logo-row { flex-direction: column; align-items: flex-start; }
}

/* ── Utilities ── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* Focus visible */
:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

