.courses-layout {
  display: flex;
  gap: 40px;
  align-items: flex-start;
}

/* ── Sidebar ── */
.courses-sidebar {
  flex: 0 0 240px;
  position: sticky;
  top: 105px;
  background: #fff;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  max-height: calc(100vh - 120px);
  overflow-y: auto;
}
.sidebar-section { border-bottom: 1px solid var(--gray-200); }
.sidebar-section:last-child { border-bottom: none; }
.sidebar-section-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  padding: 16px 16px 8px;
}
.sidebar-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  font-size: 13px;
  color: var(--dark);
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
  border: none;
  background: none;
  width: 100%;
  text-align: left;
  font-family: inherit;
}
.sidebar-item:hover { background: var(--gray-100); }
.sidebar-item.active {
  background: rgba(240,45,0,0.08);
  color: var(--red);
  font-weight: 600;
}
.sidebar-item.active .sidebar-dot { background: var(--red); }
.sidebar-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: transparent;
  transition: background var(--transition);
  flex-shrink: 0;
}
.sidebar-count {
  font-size: 11px;
  color: var(--gray-400);
  font-variant-numeric: tabular-nums;
}

/* ── Main Content ── */
.courses-main { flex: 1; min-width: 0; }

.courses-page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  flex-wrap: wrap;
  gap: 16px;
}
.courses-page-title { font-size: clamp(24px, 3vw, 36px); font-weight: 800; color: var(--dark); }
.courses-result-count { font-size: 14px; color: var(--gray-600); margin-top: 4px; }

.courses-filters {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.filter-chip {
