.filter-chip:hover { border-color: #ccc; background: var(--gray-200); }
.filter-chip.active {
  background: var(--dark);
  color: #fff;
  border-color: var(--dark);
}

.courses-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.course-card {
  background: #fff;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: transform 0.2s, box-shadow 0.2s;
