  justify-content: center;
}
.course-card-body { padding: 14px; }
.course-card-category {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--red);
  margin-bottom: 5px;
