.course-card-title { font-size: 14px; font-weight: 700; color: var(--dark); margin-bottom: 5px; line-height: 1.35; }
.course-card-instructor { font-size: 12px; color: var(--gray-600); margin-bottom: 8px; }
.course-card-rating-row { display: flex; align-items: center; gap: 5px; margin-bottom: 8px; font-size: 12px; }
.stars { color: var(--red); }
