<script>
// Sidebar category filter
function filterCourses(cat, btn) {
  document.querySelectorAll('.sidebar-item').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');

  const title = btn.textContent.trim().replace(/[\d,]+$/, '').trim();
  document.getElementById('categoryTitle').textContent = cat === 'all' ? 'All Courses' : title;

  const cards = document.querySelectorAll('#coursesGrid .course-card');
  let count = 0;
  cards.forEach(card => {
    const cats = card.dataset.category || '';
    if (cat === 'all' || cats.includes(cat)) {
      card.classList.remove('hidden');
      count++;
    } else {
      card.classList.add('hidden');
    }
  });

  document.getElementById('resultCount').textContent =
    `Showing ${count} course${count !== 1 ? 's' : ''}${cat !== 'all' ? ' in this category' : ''}`;
}

function setChip(chip, cat) {
  document.querySelectorAll('.filter-chip').forEach(c => c.classList.remove('active'));
  chip.classList.add('active');
  const allSidebar = document.querySelector('.sidebar-item.active');
  filterCourses(cat, chip);
}

// Countdown
function updateCountdown() {
  const el = document.getElementById('countdown');
  if (!el) return;
  const parts = el.textContent.split(':').map(Number);
  let [h, m, s] = parts;
  s--;
  if (s < 0) { s = 59; m--; }
  if (m < 0) { m = 59; h--; }
  if (h < 0) { h = 23; m = 59; s = 59; }
  el.textContent = [h, m, s].map(n => String(n).padStart(2, '0')).join(':');
}
setInterval(updateCountdown, 1000);
</script>
