<script>
// Field filter
function filterField(field, btn) {
  document.querySelectorAll('.field-pill').forEach(p => p.classList.remove('active'));
  btn.classList.add('active');

  document.querySelectorAll('.masonry-item').forEach(item => {
    const fields = item.dataset.field || '';
    if (field === 'all' || fields.includes(field)) {
      item.classList.remove('hidden');
    } else {
      item.classList.add('hidden');
    }
  });
}

// Sort
function sortProjects(mode) {
  const grid = document.getElementById('projectsGallery');
  const items = Array.from(grid.querySelectorAll('.masonry-item'));

  items.sort((a, b) => {
    if (mode === 'liked') return parseInt(b.dataset.likes) - parseInt(a.dataset.likes);
    if (mode === 'viewed') return parseInt(b.dataset.views) - parseInt(a.dataset.views);
    if (mode === 'recent') return Math.random() - 0.5;
    return 0;
  });

  items.forEach(item => grid.appendChild(item));
}

// Time filter (visual only in demo)
function filterByTime(period) {
  const items = document.querySelectorAll('.masonry-item');
  if (period === 'week') {
    items.forEach((item, i) => {
      item.style.display = i < 3 ? 'block' : 'none';
    });
  } else {
    items.forEach(item => item.style.display = 'block');
  }
}
</script>
