<script>
// Pricing toggle
function setPlan(plan) {
  const isYearly = plan === 'yearly';
  document.getElementById('tabYearly').classList.toggle('active', isYearly);
  document.getElementById('tabMonthly').classList.toggle('active', !isYearly);
  document.getElementById('tabYearly').setAttribute('aria-pressed', isYearly);
  document.getElementById('tabMonthly').setAttribute('aria-pressed', !isYearly);

  if (isYearly) {
    document.getElementById('planName').textContent = 'Plus — Yearly';
    document.getElementById('priceInt').textContent = '14';
    document.getElementById('priceDec').textContent = '.59';
    document.getElementById('priceBilling').textContent = 'Billed as $174.50/year';
    document.getElementById('savingsBadge').style.display = 'inline-flex';
    document.getElementById('creditsNum').textContent = '12 Plus credits';
    document.getElementById('creditsLabel').textContent = 'every year — use for any course';
    document.getElementById('ctaBtn').textContent = 'Get Plus Yearly — $14.59/mo';
    document.getElementById('priceTerms').textContent = 'Cancel subscription renewal whenever you want. After one year, renewal price will be the full amount of $349.';
  } else {
    document.getElementById('planName').textContent = 'Plus — Monthly';
    document.getElementById('priceInt').textContent = '33';
    document.getElementById('priceDec').textContent = '.90';
    document.getElementById('priceBilling').textContent = 'Billed as $33.90/month';
    document.getElementById('savingsBadge').style.display = 'none';
    document.getElementById('creditsNum').textContent = '1 Plus credit';
    document.getElementById('creditsLabel').textContent = 'every month — use for any course';
    document.getElementById('ctaBtn').textContent = 'Get Plus Monthly — $33.90/mo';
    document.getElementById('priceTerms').textContent = 'Cancel your subscription renewal at any time. No long-term commitment required.';
  }
}

// FAQ Accordion
function toggleFaq(id) {
  const item = document.getElementById(id);
  const btn = item.querySelector('.faq-question');
  const isOpen = item.classList.contains('open');

  // Close all
  document.querySelectorAll('.faq-item').forEach(i => {
    i.classList.remove('open');
    i.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
  });

  if (!isOpen) {
    item.classList.add('open');
    btn.setAttribute('aria-expanded', 'true');
  }
}

// Carousel scroll
