<script>
// Password visibility toggle
let passwordVisible = false;
function togglePassword() {
  const input = document.getElementById('password');
  const btn = document.getElementById('pwToggle');
  passwordVisible = !passwordVisible;
  input.type = passwordVisible ? 'text' : 'password';
  btn.setAttribute('aria-label', passwordVisible ? 'Hide password' : 'Show password');
  document.getElementById('eyeIcon').innerHTML = passwordVisible
    ? `<path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/>`
    : `<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>`;
}

// Form validation & submit
function handleLogin(e) {
  e.preventDefault();
  const email = document.getElementById('email');
  const password = document.getElementById('password');
  const emailErr = document.getElementById('email-error');
  const passErr = document.getElementById('password-error');
  let valid = true;

  // Reset
  [email, password].forEach(i => i.classList.remove('error'));
  [emailErr, passErr].forEach(e => e.classList.remove('visible'));

  // Validate email
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRe.test(email.value.trim())) {
    email.classList.add('error');
    emailErr.classList.add('visible');
    valid = false;
  }

  // Validate password
  if (password.value.length < 8) {
    password.classList.add('error');
    passErr.classList.add('visible');
    valid = false;
  }

  if (!valid) {
    // Focus first invalid
    const firstError = document.querySelector('.form-input.error');
    if (firstError) firstError.focus();
    return;
  }

  // Show loading
  const btn = document.getElementById('loginBtn');
  const btnText = document.getElementById('loginBtnText');
  const spinner = document.getElementById('loginSpinner');
  btn.disabled = true;
  btnText.textContent = 'Logging in…';
  spinner.style.display = 'block';

  // Simulate async login
  setTimeout(() => {
    document.getElementById('loginForm').style.display = 'none';
    document.getElementById('loginSuccess').style.display = 'flex';
  }, 1500);
}
</script>
